void BoardViewUI::cb_Start_i(Fl_Button*, void*) {
  void setNextPlayer(uint32_t);
  setupWin->hide();// hide window again
  if(wnextbut->value() ==1){
    fl_message("White to play next, with you (currently) set to play Both sides.\n - Change with Side>Player: Black, for computer to play as white.\n - - Can increase time and use Takeback for deeper search.");
    setNextPlayer(1);
    }
  else {
        fl_message("Black to play next, with you (currently) set to play Both sides.\n - Change with Side > Player: White, for computer to play as black.\n - - Can increase time and use Takeback for deeper search.");
        setNextPlayer(-1);
    }
   // set correct tick (human plays both)
   void setMouseMode (int32_t val);
   setMouseMode(0); // normal mouse input
   SideButton->activate();
   void resetAfterSetup(void);
   resetAfterSetup(); // zero times and nodeCount;
}
